        fail(EXIT_INPUT, "INPUT")
    k = raw_op["k"]
    if k not in ("D", "F", "S"):
        fail(EXIT_INPUT, "INPUT")
    a = parse_fault_num(raw_op["a"])
    z = parse_fault_num(raw_op["z"])
