    # bp 的 low/high ∈ [0, 10^6]，非 bool 整数（low 允许 0）。
    if (
        not isinstance(value, int)
        or isinstance(value, bool)
        or not 0 <= value <= 10 ** 6
    ):
        fail(EXIT_INPUT, "INPUT")
    return value


